/**
 * @name SQL injection via cursor.execute and similar APIs
 * @description Detects untrusted data flowing into Snowflake cursor.execute/execute_async and connection.execute_string
 * @kind path-problem
 * @problem.severity error
 * @id py/snowflake-sqli
 * @tags security
 *       external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SnowflakeSQLConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      // cursor.execute / execute_async
      call = API::moduleImport("snowflake.connector.cursor").getMember(["execute", "execute_async"]).getACall() or
      // connection.execute_string
      call = API::moduleImport("snowflake.connector.connection").getMember("execute_string").getACall()
      |
      sink = call.getArg(0)
    )
  }
}

module SnowflakeSQLFlow = TaintTracking::Global<SnowflakeSQLConfig>;
import SnowflakeSQLFlow::PathGraph

from SnowflakeSQLFlow::PathNode source, SnowflakeSQLFlow::PathNode sink
where SnowflakeSQLFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data flows into Snowflake SQL execution $@.", source.getNode(), "user input"

/**
 * @name Insecure use of subprocess in Snowflake connector tools
 * @description Finds uses of subprocess module that may execute shell commands with untrusted input
 * @kind path-problem
 * @problem.severity error
 * @id py/snowflake-subprocess-taint
 * @tags security
 *       external/cwe/cwe-078
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SubprocessConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(API::CallNode call |
      call = API::moduleImport("subprocess").getMember(["Popen", "call", "check_call", "check_output", "run"]).getACall() |
      sink = call.getArg(0)
    )
  }
}

module SubprocessFlow = TaintTracking::Global<SubprocessConfig>;
import SubprocessFlow::PathGraph

from SubprocessFlow::PathNode source, SubprocessFlow::PathNode sink
where SubprocessFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "User-controlled data flows into subprocess execution $@.", source.getNode(), "user input"
